window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-25801e8fa3cb3389"]={"versions": [{"id": "FIG-25801e8fa3cb3389", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Bit-/Byte-Layout (Protokoll-Header-Spezifikation).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Spezifiziert im AUTOSAR Foundation / Classic & Adaptive Platform Standard (<code>AUTOSAR_PRS_E2EProtocol</code>, <code>AUTOSAR_SWS_E2ELibrary</code>).</li>\n<li>Definiert das On-Wire-Serialisierungsformat des Headers für <strong>E2E Profile 5</strong> innerhalb des E2E-Stacks (Black-Channel-Kommunikationsabsicherung gemäß ISO 26262 bis ASIL D).</li>\n<li>Ziel ist die Erkennung von Übertragungsfehlern (Verfälschung, Wiederholung, Einfügung, Verlust, Vertauschung) bei minimalem Protokoll-Overhead (3 Byte) über CAN, CAN FD, FlexRay oder Ethernet (SOME/IP).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Header-Struktur & Bit-/Byte-Mapping (Gesamtgröße: 24 Bit / 3 Byte):</strong></li>\n<li><strong>Byte 0–1 (Bit 0 bis 15): <code>E2E CRC</code></strong></li>\n<li>16-Bit-Prüfsumme zur Integritätsabsicherung.</li>\n<li>Berechnet mittels standardisiertem CRC-16-Polynom (0x1021 / CRC-16-CCITT bzw. AUTOSAR-konformes CRC16, Initialwert 0xFFFF).</li>\n<li>Byte-Reihenfolge innerhalb des Headers: Byte 0 (Bit 0..7) und Byte 1 (Bit 8..15) entsprechend der spezifizierten Endianness-Regel für Profile 5 (CRC wird standardmäßig im definierten Byte-Offset serialisiert).</li>\n<li><strong>Byte 2 (Bit 16 bis 23): <code>E2E Counter</code></strong></li>\n<li>8-Bit-Sequenzzähler (Wertebereich: <code>0x00</code> bis <code>0xFF</code>, zyklischer Überlauf nach 255).</li>\n<li>Dient der Erkennung von Nachrichtenwiederholung, Verlust und unzulässiger Einfügung/Reordering.</li>\n<li><strong>Implizite Entitäten (nicht im Header übertragen):</strong></li>\n<li><strong><code>Data ID</code> (16 Bit):</strong> Geht als sender- und empfängerseitig konfigurierte Konstante implizit in die CRC-16-Berechnung ein (Verhinderung von Masquerading / Fehlrouting ohne On-Wire-Payload-Belastung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sender-Pfade (<code>E2E_P05Protect</code> / <code>E2E_P05ProtectInit</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Inkrementierung des internen 8-Bit-Counters um 1 (Modulo 256).</li>\n<li>Schreiben des Zählerwerts in Byte 2 des reservierten Header-Bereichs.</li>\n<li>Berechnung des 16-Bit-CRC über:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die konfigurierten Nutzdatenbytes (Payload),</li>\n<li>Den 8-Bit-Counter (Byte 2),</li>\n<li>Die 16-Bit <code>Data ID</code> (in der Regel als zwei Bytes im Berechnungsstrom vorangestellt oder angehängt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schreiben des CRC in Byte 0 und 1.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfänger-Pfade (<code>E2E_P05Check</code> / <code>E2E_P05CheckInit</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Extraktion von CRC (Byte 0..1) und Counter (Byte 2) an der konfigurierten Offset-Position.</li>\n<li>Unabhängige Neuberechnung des CRC-16 über Payload, extrahierten Counter und die lokal hinterlegte <code>Data ID</code>.</li>\n<li>Vergleich des empfangenen CRC mit dem berechneten CRC:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Diskrepanz $\\rightarrow$ Status <code>E2E_P05STATUS_WRONGCRC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Prüfung des Counters gegen den vorherigen Empfangswert unter Berücksichtigung des zulässigen Delta-Fensters:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Identisch $\\rightarrow$ <code>E2E_P05STATUS_REPEATED</code>.</li>\n<li>Zählerabstand innerhalb <code>MaxDeltaCounter</code> $\\rightarrow$ <code>E2E_P05STATUS_OK</code> bzw. <code>E2E_P05STATUS_OKSOMELOST</code>.</li>\n<li>Zählerabstand außerhalb $\\rightarrow$ <code>E2E_P05STATUS_WRONGSEQUENCE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückgabe des Profil-Status an den E2E State Machine Manager (<code>E2E_SMCheck</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Layout & Konfiguration (<code>Offset</code>):</strong></li>\n<li>Die Position des 3-Byte-Headers innerhalb der PDU ist über den Parameter <code>Offset</code> (in Bits, Byte-Alignment zwingend empfohlen: <code>Offset % 8 == 0</code>) im E2E-Konfigurationsdeskriptor (<code>E2E_P05ConfigType</code>) frei platzierbar.</li>\n<li>Payloads können vor, nach oder um den Header herum angeordnet sein. Der Bereich von Bit 0..23 relativ zum konfigurierten Offset darf von Nutzdaten nicht überlappt werden.</li>\n<li><strong>Payload-Längenbereich:</strong></li>\n<li>Profile 5 unterstützt variable sowie feste Datenlängen bis zu 4096 Byte (<code>DataLength</code> $\\le 32768$ Bit).</li>\n<li><strong>Stack-Integration:</strong></li>\n<li>Classic Platform: Typischer Aufruf innerhalb des COM-Stacks (E2E-Wrapper im RTE/Com-Layer oder E2E-PduR-Callout).</li>\n<li>Adaptive Platform: Serialisierung über die <code>ara::com</code>-E2E-Schicht direkt im Signal-/Methoden-Payload vor Übergabe an den IPC/SOME/IP-Binding-Layer.</li>\n<li><strong>Performance-Hinweis:</strong></li>\n<li>Der 8-Bit-Counter vergrößert die Erkennungssicherheit gegen Paketverluste/Reordering im Vergleich zu Profil 1/2 (4-Bit-Counter) erheblich, während der 16-Bit-CRC im Vergleich zu Profil 4/7 (32-Bit-CRC) Bandbreite auf CAN FD spart.</li>\n</ul>"}, {"id": "FIG-eeeae605157cad1c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Bit-/Byte-Layout (Protokoll-Header-Spezifikation).</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Spezifiziert im AUTOSAR Foundation / Classic & Adaptive Platform Standard (<code>AUTOSAR_PRS_E2EProtocol</code>, <code>AUTOSAR_SWS_E2ELibrary</code>).</li>\n<li>Definiert das On-Wire-Serialisierungsformat des Headers für <strong>E2E Profile 5</strong> innerhalb des E2E-Stacks (Black-Channel-Kommunikationsabsicherung gemäß ISO 26262 bis ASIL D).</li>\n<li>Ziel ist die Erkennung von Übertragungsfehlern (Verfälschung, Wiederholung, Einfügung, Verlust, Vertauschung) bei minimalem Protokoll-Overhead (3 Byte) über CAN, CAN FD, FlexRay oder Ethernet (SOME/IP).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Header-Struktur & Bit-/Byte-Mapping (Gesamtgröße: 24 Bit / 3 Byte):</strong></li>\n<li><strong>Byte 0–1 (Bit 0 bis 15): <code>E2E CRC</code></strong></li>\n<li>16-Bit-Prüfsumme zur Integritätsabsicherung.</li>\n<li>Berechnet mittels standardisiertem CRC-16-Polynom (0x1021 / CRC-16-CCITT bzw. AUTOSAR-konformes CRC16, Initialwert 0xFFFF).</li>\n<li>Byte-Reihenfolge innerhalb des Headers: Byte 0 (Bit 0..7) und Byte 1 (Bit 8..15) entsprechend der spezifizierten Endianness-Regel für Profile 5 (CRC wird standardmäßig im definierten Byte-Offset serialisiert).</li>\n<li><strong>Byte 2 (Bit 16 bis 23): <code>E2E Counter</code></strong></li>\n<li>8-Bit-Sequenzzähler (Wertebereich: <code>0x00</code> bis <code>0xFF</code>, zyklischer Überlauf nach 255).</li>\n<li>Dient der Erkennung von Nachrichtenwiederholung, Verlust und unzulässiger Einfügung/Reordering.</li>\n<li><strong>Implizite Entitäten (nicht im Header übertragen):</strong></li>\n<li><strong><code>Data ID</code> (16 Bit):</strong> Geht als sender- und empfängerseitig konfigurierte Konstante implizit in die CRC-16-Berechnung ein (Verhinderung von Masquerading / Fehlrouting ohne On-Wire-Payload-Belastung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Sender-Pfade (<code>E2E_P05Protect</code> / <code>E2E_P05ProtectInit</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Inkrementierung des internen 8-Bit-Counters um 1 (Modulo 256).</li>\n<li>Schreiben des Zählerwerts in Byte 2 des reservierten Header-Bereichs.</li>\n<li>Berechnung des 16-Bit-CRC über:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die konfigurierten Nutzdatenbytes (Payload),</li>\n<li>Den 8-Bit-Counter (Byte 2),</li>\n<li>Die 16-Bit <code>Data ID</code> (in der Regel als zwei Bytes im Berechnungsstrom vorangestellt oder angehängt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Schreiben des CRC in Byte 0 und 1.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Empfänger-Pfade (<code>E2E_P05Check</code> / <code>E2E_P05CheckInit</code>):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Extraktion von CRC (Byte 0..1) und Counter (Byte 2) an der konfigurierten Offset-Position.</li>\n<li>Unabhängige Neuberechnung des CRC-16 über Payload, extrahierten Counter und die lokal hinterlegte <code>Data ID</code>.</li>\n<li>Vergleich des empfangenen CRC mit dem berechneten CRC:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Diskrepanz $\\rightarrow$ Status <code>E2E_P05STATUS_WRONGCRC</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Prüfung des Counters gegen den vorherigen Empfangswert unter Berücksichtigung des zulässigen Delta-Fensters:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Identisch $\\rightarrow$ <code>E2E_P05STATUS_REPEATED</code>.</li>\n<li>Zählerabstand innerhalb <code>MaxDeltaCounter</code> $\\rightarrow$ <code>E2E_P05STATUS_OK</code> bzw. <code>E2E_P05STATUS_OKSOMELOST</code>.</li>\n<li>Zählerabstand außerhalb $\\rightarrow$ <code>E2E_P05STATUS_WRONGSEQUENCE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Rückgabe des Profil-Status an den E2E State Machine Manager (<code>E2E_SMCheck</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PDU-Layout & Konfiguration (<code>Offset</code>):</strong></li>\n<li>Die Position des 3-Byte-Headers innerhalb der PDU ist über den Parameter <code>Offset</code> (in Bits, Byte-Alignment zwingend empfohlen: <code>Offset % 8 == 0</code>) im E2E-Konfigurationsdeskriptor (<code>E2E_P05ConfigType</code>) frei platzierbar.</li>\n<li>Payloads können vor, nach oder um den Header herum angeordnet sein. Der Bereich von Bit 0..23 relativ zum konfigurierten Offset darf von Nutzdaten nicht überlappt werden.</li>\n<li><strong>Payload-Längenbereich:</strong></li>\n<li>Profile 5 unterstützt variable sowie feste Datenlängen bis zu 4096 Byte (<code>DataLength</code> $\\le 32768$ Bit).</li>\n<li><strong>Stack-Integration:</strong></li>\n<li>Classic Platform: Typischer Aufruf innerhalb des COM-Stacks (E2E-Wrapper im RTE/Com-Layer oder E2E-PduR-Callout).</li>\n<li>Adaptive Platform: Serialisierung über die <code>ara::com</code>-E2E-Schicht direkt im Signal-/Methoden-Payload vor Übergabe an den IPC/SOME/IP-Binding-Layer.</li>\n<li><strong>Performance-Hinweis:</strong></li>\n<li>Der 8-Bit-Counter vergrößert die Erkennungssicherheit gegen Paketverluste/Reordering im Vergleich zu Profil 1/2 (4-Bit-Counter) erheblich, während der 16-Bit-CRC im Vergleich zu Profil 4/7 (32-Bit-CRC) Bandbreite auf CAN FD spart.</li>\n</ul>"}], "trans": [{"from": "FIG-25801e8fa3cb3389", "to": "FIG-eeeae605157cad1c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
